define(['Magento_ReCaptchaWebapiUi/js/webapiReCaptcha','jquery'],function(Component,$){'use strict';var reCaptchaIds=new WeakMap(),uuid=0;return Component.extend({defaults:{template:'Magento_ReCaptchaCheckout/reCaptcha',skipPayments:[]},renderReCaptchaFor:function(method){var reCaptcha;if(this.isCheckoutReCaptchaRequiredFor(method)){reCaptcha=$.extend(true,{},this,{reCaptchaId:this.getReCaptchaIdFor(method)});reCaptcha.renderReCaptcha();}},getReCaptchaIdFor:function(method){if(!reCaptchaIds.has(method)){reCaptchaIds.set(method,this.getReCaptchaId()+'-'+uuid++);}
return reCaptchaIds.get(method);},isCheckoutReCaptchaRequiredFor:function(method){return!this.skipPayments||!this.skipPayments.hasOwnProperty(method.getCode());},initCaptcha:function(){var $wrapper,$recaptchaResponseInput;this._super();$wrapper=$('#'+this.getReCaptchaId()+'-wrapper');$recaptchaResponseInput=$wrapper.find('[name=g-recaptcha-response]');if($recaptchaResponseInput.length){$recaptchaResponseInput.prop('disabled',true);}}});});